sys_ui_page.client_script:
var autoCareState = {
    currentPage: "home",
    currentVehicleId: "",
    selectedService: "Brake Inspection",
    selectedTime: "11:00 AM",
    data: {user:{},vehicles:[],appointments:[],inspections:[],recommendations:[],repairs:[],outcomes:[],history:[],invoices:[],backend:{}}
};

function el(id) {
    return document.getElementById(id);
}

function setText(id, value) {
    var node = el(id);
    if (node) node.textContent = value === null || value === undefined || value === "" ? "Not recorded" : String(value);
}

function clean(value) {
    if (value === null || value === undefined || value === "") return "Not recorded";
    return String(value);
}

function esc(value) {
    return clean(value)
        .replace(/&/g, "&amp;")
        .replace(/</g, "&lt;")
        .replace(/>/g, "&gt;")
        .replace(/"/g, "&quot;")
        .replace(/'/g, "&#39;");
}

function vehicleName(v) {
    if (!v) return "Vehicle";
    var name = ((v.make || "") + " " + (v.model || "")).replace(/^\s+|\s+$/g, "");
    return name || v.registration || "Vehicle";
}

function currentVehicle() {
    var vehicles = autoCareState.data.vehicles || [];
    if (!vehicles.length) return null;
    for (var i = 0; i < vehicles.length; i++) {
        if (vehicles[i].sys_id === autoCareState.currentVehicleId) return vehicles[i];
    }
    return vehicles[0];
}

function recordMatchesVehicle(record, vehicle) {
    if (!record || !vehicle) return false;
    if (record.vehicle_id && record.vehicle_id === vehicle.sys_id) return true;
    var rv = String(record.vehicle || "").toLowerCase();
    var names = [vehicleName(vehicle), vehicle.registration, vehicle.sys_id].join(" ").toLowerCase();
    if (rv && names.indexOf(rv) >= 0) return true;
    if (rv && vehicle.registration && rv === String(vehicle.registration).toLowerCase()) return true;
    if (rv && vehicleName(vehicle) && rv === vehicleName(vehicle).toLowerCase()) return true;
    return false;
}

function recordsForVehicle(records, vehicle) {
    var out = [];
    for (var i = 0; i < (records || []).length; i++) {
        if (recordMatchesVehicle(records[i], vehicle)) out.push(records[i]);
    }
    return out;
}

function latest(records) {
    return records && records.length ? records[0] : null;
}

function badgeClass(value) {
    var s = String(value || "").toLowerCase();
    if (s.indexOf("high") >= 0 || s.indexOf("critical") >= 0 || s.indexOf("required") >= 0 || s.indexOf("failed") >= 0) return "high";
    if (s.indexOf("medium") >= 0 || s.indexOf("pending") >= 0 || s.indexOf("recommended") >= 0 || s.indexOf("review") >= 0) return "medium";
    if (s.indexOf("complete") >= 0 || s.indexOf("approved") >= 0 || s.indexOf("paid") >= 0 || s.indexOf("success") >= 0) return "good";
    return "info";
}

function badge(value) {
    return '<span class="badge ' + badgeClass(value) + '">' + esc(value || "Not specified") + '</span>';
}

function setCount(id, value) {
    setText(id, String(value || 0));
}

function calculateHealth(vehicle) {
    var inspections = recordsForVehicle(autoCareState.data.inspections, vehicle);
    var recs = recordsForVehicle(autoCareState.data.recommendations, vehicle);
    var score = 100;
    var debt = 0;
    var latestInspection = latest(inspections);
    var severity = latestInspection ? String(latestInspection.severity || "").toLowerCase() : "";
    if (severity.indexOf("critical") >= 0) score -= 30;
    else if (severity.indexOf("high") >= 0) score -= 20;
    else if (severity.indexOf("medium") >= 0) score -= 10;
    else if (severity.indexOf("low") >= 0) score -= 5;

    for (var i = 0; i < recs.length; i++) {
        var cls = String(recs[i].classification || recs[i].priority || "").toLowerCase();
        if (cls.indexOf("required") >= 0 || cls.indexOf("high") >= 0) { score -= 8; debt += 1; }
        else if (cls.indexOf("recommended") >= 0 || cls.indexOf("medium") >= 0) { score -= 4; debt += 1; }
        if (String(recs[i].review_status || "").toLowerCase().indexOf("pending") >= 0) debt += 1;
    }
    if (score < 0) score = 0;
    if (score > 100) score = 100;
    return {score:score, debt:debt};
}

function go(page) {
    var pages = document.querySelectorAll(".page");
    for (var i = 0; i < pages.length; i++) pages[i].classList.remove("active");
    var target = el(page);
    if (target) target.classList.add("active");

    var buttons = document.querySelectorAll(".nav button[data-page]");
    for (var j = 0; j < buttons.length; j++) {
        buttons[j].classList.toggle("active", buttons[j].getAttribute("data-page") === page);
    }
    autoCareState.currentPage = page;
    window.scrollTo(0, 0);
}

function initNavigation() {
    var navButtons = document.querySelectorAll(".nav button[data-page]");
    for (var i = 0; i < navButtons.length; i++) {
        navButtons[i].addEventListener("click", function () {
            go(this.getAttribute("data-page"));
        });
    }
    var goButtons = document.querySelectorAll("[data-go]");
    for (var j = 0; j < goButtons.length; j++) {
        goButtons[j].addEventListener("click", function () {
            go(this.getAttribute("data-go"));
        });
    }
}

function initVehicleSelector() {
    var selector = el("vehicleSelector");
    if (!selector) return;
    selector.innerHTML = "";
    var vehicles = autoCareState.data.vehicles || [];
    for (var i = 0; i < vehicles.length; i++) {
        var option = document.createElement("option");
        option.value = vehicles[i].sys_id;
        option.textContent = vehicleName(vehicles[i]) + (vehicles[i].registration ? " - " + vehicles[i].registration : "");
        selector.appendChild(option);
    }
    var v = currentVehicle();
    if (v) selector.value = v.sys_id;
    selector.addEventListener("change", function () {
        autoCareState.currentVehicleId = this.value;
        renderAll();
    });
}

function renderHome() {
    var v = currentVehicle();
    if (!v) return;
    setText("homeVehicleName", vehicleName(v));
    setText("homeRegistration", v.registration);
    setText("homeMileage", v.mileage);
    setText("homeOwner", v.owner);
    setText("homeStatus", v.status);
    setCount("countVehicles", autoCareState.data.vehicles.length);
    setCount("countAppointments", autoCareState.data.appointments.length);
    setCount("countInspections", autoCareState.data.inspections.length);
    setCount("countRecommendations", autoCareState.data.recommendations.length);
    setCount("countRepairs", autoCareState.data.repairs.length);
    setCount("countOutcomes", autoCareState.data.outcomes.length);
    setCount("countHistory", autoCareState.data.history.length);
    setCount("countInvoices", autoCareState.data.invoices.length);

    var inspections = recordsForVehicle(autoCareState.data.inspections, v);
    var recs = recordsForVehicle(autoCareState.data.recommendations, v);
    var history = recordsForVehicle(autoCareState.data.history, v);
    var i = latest(inspections), r = latest(recs);
    setText("homeSeverity", i ? i.severity : "No inspection");
    setText("homeFinding", i ? (i.finding || i.technician_notes) : "No inspection recorded");
    setText("homeInspectionStatus", i ? i.status : "No inspection");
    setText("homeLastService", history.length ? history[0].date : v.last_service_date);
    setText("homeRecommendation", r ? (r.issue || r.description || "Recommendation available") : "No recommendation available");
    setText("homeRecommendationClass", r ? (r.classification || "Not specified") : "Not specified");
    setText("homeRecommendationPriority", r ? (r.priority || "Not specified") : "Not specified");
}

function renderPassport() {
    var v = currentVehicle();
    if (!v) return;
    var inspections = recordsForVehicle(autoCareState.data.inspections, v);
    var recs = recordsForVehicle(autoCareState.data.recommendations, v);
    var history = recordsForVehicle(autoCareState.data.history, v);
    var invoices = recordsForVehicle(autoCareState.data.invoices, v);
    var appointments = recordsForVehicle(autoCareState.data.appointments, v);
    var outcomes = recordsForVehicle(autoCareState.data.outcomes, v);
    var score = calculateHealth(v);
    var latestHistory = latest(history), latestInspection = latest(inspections), latestRec = latest(recs);

    setText("passportReg", v.registration);
    setText("passportMileage", v.mileage);
    setText("healthScore", score.score);
    var ring = el("scoreRing"); if (ring) ring.style.setProperty("--score", score.score + "%");
    setText("maintenanceDebt", score.debt);
    setText("passportLastService", latestHistory ? latestHistory.date : v.last_service_date);
    setText("passportLastServiceCenter", latestHistory ? latestHistory.center : v.service_center);
    setText("passportMakeModel", vehicleName(v));
    setText("passportYearColor", v.color || "Year not recorded");
    setText("passportOwner", v.owner);
    setText("passportStatus", v.status);
    setText("passportNextService", latestHistory ? latestHistory.next_date : "Not recorded");
    setText("passportNextMileage", latestHistory ? latestHistory.next_mileage : "Not recorded");
    setCount("passportServiceCount", history.length); setCount("passportInvoiceCount", invoices.length);
    setCount("healthInspectionCount", inspections.length); setCount("healthHistoryCount", history.length); setCount("healthRecommendationCount", recs.length);
    var ib = el("healthInspectionBar"), hb = el("healthHistoryBar"), rb = el("healthRecommendationBar");
    if (ib) ib.style.width = Math.min(100, inspections.length * 7) + "%";
    if (hb) hb.style.width = Math.min(100, history.length * 7) + "%";
    if (rb) rb.style.width = Math.min(100, recs.length * 7) + "%";
    setText("passportComplianceStatus", v.status); setText("passportComplianceService", v.last_service_date || (latestHistory ? latestHistory.date : "Not recorded"));

    var timeline = el("passportTimeline");
    if (timeline) {
        var html = "";
        if (latestHistory) html += '<div class="timeline-item"><h4>Latest Service</h4><p>' + esc(latestHistory.date) + ' — ' + esc(latestHistory.details || latestHistory.description) + '</p></div>';
        if (latestInspection) html += '<div class="timeline-item"><h4>Latest Inspection</h4><p>' + esc(latestInspection.date) + ' — ' + esc(latestInspection.finding || latestInspection.technician_notes) + '</p></div>';
        if (latestRec) html += '<div class="timeline-item"><h4>Latest AI Recommendation</h4><p>' + esc(latestRec.issue || latestRec.action) + '</p></div>';
        if (appointments.length) html += '<div class="timeline-item"><h4>Latest Appointment</h4><p>' + esc(appointments[0].appointment_date) + ' — ' + esc(appointments[0].service_type) + '</p></div>';
        if (!html) html = '<div class="empty">No timeline records are available for this vehicle.</div>';
        timeline.innerHTML = html;
    }
    renderPassportRows(history, invoices, appointments, outcomes);
}

function renderPassportRows(history, invoices, appointments, outcomes) {
    var h = el("passportServiceRows"), i = el("passportInvoiceRows"), a = el("passportAppointmentRows"), o = el("passportOutcomeRows");
    if (h) { h.innerHTML = history.length ? history.map(function(r){return '<tr><td>'+esc(r.date)+'</td><td>'+esc(r.vehicle)+'</td><td>'+esc(r.details || r.description)+'</td><td>'+esc(r.parts)+'</td><td>'+esc(r.mileage)+'</td><td>'+esc(r.cost)+'</td><td>'+esc(r.next_date)+'</td></tr>';}).join("") : '<tr><td colspan="7" class="empty">No service history for this vehicle.</td></tr>'; }
    if (i) { i.innerHTML = invoices.length ? invoices.map(function(r){return '<tr><td><b>'+esc(r.number)+'</b></td><td>'+esc(r.date)+'</td><td>'+esc(r.amount)+'</td><td>'+badge(r.payment)+'</td><td>'+esc(r.document_status)+'</td></tr>';}).join("") : '<tr><td colspan="5" class="empty">No invoices for this vehicle.</td></tr>'; }
    if (a) { a.innerHTML = appointments.length ? appointments.map(function(r){return '<tr><td>'+esc(r.number)+'</td><td>'+esc(r.appointment_date)+'</td><td>'+esc(r.service_type)+'</td><td>'+badge(r.status)+'</td></tr>';}).join("") : '<tr><td colspan="4" class="empty">No appointments for this vehicle.</td></tr>'; }
    if (o) { o.innerHTML = outcomes.length ? outcomes.map(function(r){return '<tr><td>'+esc(r.number)+'</td><td>'+esc(r.date)+'</td><td>'+esc(r.type)+'</td><td>'+badge(r.final_status)+'</td><td>'+esc(r.quality)+'</td></tr>';}).join("") : '<tr><td colspan="5" class="empty">No verified outcomes for this vehicle.</td></tr>'; }
}

function renderRecommendations() {
    var recs = autoCareState.data.recommendations || [];
    setCount("recTotal", recs.length);
    var required=0, high=0, review=0;
    for (var i=0;i<recs.length;i++) {
        var c=String(recs[i].classification||"").toLowerCase(), p=String(recs[i].priority||"").toLowerCase(), rs=String(recs[i].review_status||"").toLowerCase();
        if (c.indexOf("required")>=0) required++;
        if (p.indexOf("high")>=0 || c.indexOf("required")>=0) high++;
        if (rs.indexOf("pending")>=0 || rs.indexOf("review")>=0) review++;
    }
    setCount("recRequired",required); setCount("recHigh",high); setCount("recReview",review);
    var v=currentVehicle(), current=recordsForVehicle(recs,v), latestRec=latest(current);
    setText("aiIssue", latestRec ? latestRec.issue : "No recommendation recorded");
    setText("aiClass", latestRec ? latestRec.classification : "Not specified");
    setText("aiAction", latestRec ? latestRec.action : "Not specified");
    setText("aiEvidence", latestRec ? ((latestRec.description || "") + (latestRec.source ? " Source: " + latestRec.source + "." : "")) : "Recommendation evidence is taken directly from backend Recommendation records.");
    var cards=el("recommendationCards");
    if (!cards) return;
    if (!recs.length) { cards.innerHTML='<div class="card empty">No recommendation records are available.</div>'; return; }
    cards.innerHTML=recs.map(function(r){return '<div class="recommendation"><div class="recommendation-head"><h3>'+esc(r.issue||r.description||"Recommendation")+'</h3>'+badge(r.classification)+'</div><div class="rec-meta">'+badge(r.priority||"Priority not specified")+badge(r.review_status||"Review status not specified")+badge(r.source||"Source not specified")+'</div><div class="rec-detail"><b>Action:</b> '+esc(r.action)+'<br/><b>Vehicle:</b> '+esc(r.vehicle)+'<br/><b>Confidence:</b> '+esc(r.ai_confidence||r.confidence)+'<br/><b>Estimated Cost:</b> '+esc(r.estimated_cost)+'<br/><b>Due:</b> '+esc(r.due_date)+'</div></div>';}).join("");
}

function renderAppointments() {
    var rows=el("appointmentRows"), data=autoCareState.data.appointments||[];
    if (!rows) return;
    rows.innerHTML=data.length?data.map(function(r){return '<tr><td><b>'+esc(r.number)+'</b></td><td>'+esc(r.vehicle)+'</td><td>'+esc(r.appointment_date)+'</td><td>'+esc(r.preferred_time)+'</td><td>'+esc(r.service_type)+'</td><td>'+esc(r.technician)+'</td><td>'+badge(r.status)+'</td></tr>';}).join(""):'<tr><td colspan="7" class="empty">No appointment records are available.</td></tr>';
    var v=currentVehicle(); if(v){setText("bookingVehicleName",vehicleName(v));setText("bookingVehicleReg",v.registration);var hidden=el("bookingVehicle");if(hidden)hidden.value=v.sys_id;}
}

function renderInspection() {
    var data=autoCareState.data.inspections||[];
    setCount("inspectionTotal",data.length); var high=0,complete=0,findings=0;
    for(var i=0;i<data.length;i++){var s=String(data[i].severity||"").toLowerCase(),st=String(data[i].status||"").toLowerCase();if(s.indexOf("high")>=0||s.indexOf("critical")>=0)high++;if(st.indexOf("complete")>=0)complete++;if(data[i].finding||data[i].technician_notes)findings++;}
    setCount("inspectionHigh",high);setCount("inspectionCompleted",complete);setCount("inspectionFindings",findings);
    var rows=el("inspectionRows");if(!rows)return;
    rows.innerHTML=data.length?data.map(function(r){return '<tr><td><b>'+esc(r.number)+'</b></td><td>'+esc(r.vehicle)+'</td><td>'+esc(r.appointment)+'</td><td>'+esc(r.date)+'</td><td>'+esc(r.technician)+'</td><td>'+badge(r.severity)+'</td><td>'+badge(r.status)+'</td><td>'+esc(r.finding||r.technician_notes)+'</td><td>'+esc(r.recommendation)+'</td></tr>';}).join(""):'<tr><td colspan="9" class="empty">No inspection records are available.</td></tr>';
}

function renderRepair() {
    var data=autoCareState.data.repairs||[];setCount("repairTotal",data.length);var pending=0,approved=0,total=0;
    for(var i=0;i<data.length;i++){var a=String(data[i].approval||"").toLowerCase(),s=String(data[i].status||"").toLowerCase();if(a.indexOf("approved")<0 && s.indexOf("approved")<0)pending++;else approved++;var n=parseFloat(String(data[i].cost||"").replace(/[^0-9.\-]/g,""));if(!isNaN(n))total+=n;}
    setCount("repairPending",pending);setCount("repairApproved",approved);setText("repairCost",total?total.toFixed(2):"Not recorded");
    var rows=el("repairRows");if(!rows)return;
    rows.innerHTML=data.length?data.map(function(r){var action=(String(r.approval||"").toLowerCase().indexOf("approved")<0 && String(r.status||"").toLowerCase().indexOf("approved")<0)?'<button type="button" class="outline repair-approve" data-repair-id="'+esc(r.sys_id)+'">Approve</button>':'<span class="badge good">Approved</span>';return '<tr><td><b>'+esc(r.number)+'</b></td><td>'+esc(r.vehicle)+'</td><td>'+esc(r.description)+'</td><td>'+badge(r.classification)+'</td><td>'+esc(r.cost)+'</td><td>'+esc(r.evidence)+'</td><td>'+esc(r.approval)+'</td><td>'+badge(r.status)+'</td><td>'+action+'</td></tr>';}).join(""):'<tr><td colspan="9" class="empty">No repair plan records are available.</td></tr>';
    var btns=document.querySelectorAll(".repair-approve");for(var j=0;j<btns.length;j++){btns[j].addEventListener("click",function(){approveRepair(this.getAttribute("data-repair-id"));});}
}

function renderOutcomes() {
    var data=autoCareState.data.outcomes||[];setCount("outcomeTotal",data.length);var completed=0,follow=0,totalQ=0,qCount=0;
    for(var i=0;i<data.length;i++){var st=String(data[i].final_status||"").toLowerCase(),fu=String(data[i].follow_up||"").toLowerCase();if(st.indexOf("complete")>=0)completed++;if(fu && fu!=="no" && fu!=="false")follow++;var q=parseFloat(String(data[i].quality||"").replace(/[^0-9.\-]/g,""));if(!isNaN(q)){totalQ+=q;qCount++;}}
    setCount("outcomeCompleted",completed);setCount("outcomeFollowup",follow);setText("outcomeQuality",qCount?(totalQ/qCount).toFixed(1):"Not recorded");
    var rows=el("outcomeRows");if(!rows)return;rows.innerHTML=data.length?data.map(function(r){return '<tr><td><b>'+esc(r.number)+'</b></td><td>'+esc(r.vehicle)+'</td><td>'+esc(r.date)+'</td><td>'+esc(r.type)+'</td><td>'+esc(r.description)+'</td><td>'+esc(r.parts)+'</td><td>'+badge(r.final_status)+'</td><td>'+esc(r.quality)+'</td><td>'+esc(r.follow_up)+'</td></tr>';}).join(""):'<tr><td colspan="9" class="empty">No service outcome records are available.</td></tr>';
}

function renderHistory() {
    var data=autoCareState.data.history||[];setCount("historyTotal",data.length);setText("historyLatest",data.length?data[0].date:"Not recorded");var total=0;for(var i=0;i<data.length;i++){var n=parseFloat(String(data[i].cost||"").replace(/[^0-9.\-]/g,""));if(!isNaN(n))total+=n;}setText("historyCost",total?total.toFixed(2):"Not recorded");
    var rows=el("historyRows");if(!rows)return;rows.innerHTML=data.length?data.map(function(r){return '<tr><td>'+esc(r.date)+'</td><td>'+esc(r.vehicle)+'</td><td>'+esc(r.details||r.description)+'</td><td>'+esc(r.parts)+'</td><td>'+esc(r.mileage)+'</td><td>'+esc(r.cost)+'</td><td>'+esc(r.center)+'</td><td>'+esc(r.next_date)+' / '+esc(r.next_mileage)+'</td></tr>';}).join(""):'<tr><td colspan="8" class="empty">No service history records are available.</td></tr>';
}

function renderInvoices() {
    var data=autoCareState.data.invoices||[];setCount("invoiceTotal",data.length);var total=0,paid=0,pending=0;for(var i=0;i<data.length;i++){var n=parseFloat(String(data[i].amount||"").replace(/[^0-9.\-]/g,""));if(!isNaN(n))total+=n;var p=String(data[i].payment||"").toLowerCase();if(p.indexOf("paid")>=0)paid++;else pending++;}setText("invoiceAmount",total?total.toFixed(2):"Not recorded");setCount("invoicePaid",paid);setCount("invoicePending",pending);
    var rows=el("invoiceRows");if(!rows)return;rows.innerHTML=data.length?data.map(function(r){return '<tr><td><b>'+esc(r.number)+'</b></td><td>'+esc(r.date)+'</td><td>'+esc(r.vehicle)+'</td><td>'+esc(r.description)+'</td><td>'+esc(r.amount)+'</td><td>'+badge(r.payment)+'</td><td>'+esc(r.due)+'</td><td>'+esc(r.document_status)+'</td><td>'+esc(r.center)+'</td></tr>';}).join(""):'<tr><td colspan="9" class="empty">No invoice records are available.</td></tr>';
}

function renderProfile() {
    var d=autoCareState.data;var v=currentVehicle();setText("profileEmailText",d.user.email||"Email not recorded");setCount("profileVehicleCount",d.vehicles.length);setCount("profileServiceCount",d.history.length);setCount("profileAppointmentCount",d.appointments.length);var email=el("profileEmail");if(email)email.value=d.user.email||"";var vfield=el("profileVehicle"),rfield=el("profileRegistration");if(vfield)vfield.value=v?vehicleName(v):"";if(rfield)rfield.value=v?v.registration:"";
}

function initTabs() {
    var tabs=document.querySelectorAll(".tab[data-tab]");for(var i=0;i<tabs.length;i++){tabs[i].addEventListener("click",function(){var key=this.getAttribute("data-tab");for(var j=0;j<tabs.length;j++)tabs[j].classList.remove("active");this.classList.add("active");var panes=document.querySelectorAll(".passport-tab");for(var k=0;k<panes.length;k++)panes[k].style.display="none";var pane=el("passport-"+key);if(pane)pane.style.display="block";});}
}

function initBooking() {
    var services=document.querySelectorAll(".service-option");for(var i=0;i<services.length;i++){services[i].addEventListener("click",function(){for(var j=0;j<services.length;j++)services[j].classList.remove("selected");this.classList.add("selected");autoCareState.selectedService=this.getAttribute("data-service")||this.textContent;setText("bookingServiceText",autoCareState.selectedService);var h=el("bookingServiceHidden");if(h)h.value=autoCareState.selectedService;});}
    var slots=document.querySelectorAll(".slot");for(var s=0;s<slots.length;s++){slots[s].addEventListener("click",function(){for(var j=0;j<slots.length;j++)slots[j].classList.remove("selected");this.classList.add("selected");autoCareState.selectedTime=this.getAttribute("data-time")||this.textContent;setText("bookingTimeText",autoCareState.selectedTime);var h=el("bookingTimeHidden");if(h)h.value=autoCareState.selectedTime;});}
    var date=el("bookingDate");if(date){date.addEventListener("change",function(){setText("bookingDateText",formatDate(this.value));var h=el("bookingDateHidden");if(h)h.value=this.value;});var now=new Date(),m=String(now.getMonth()+1),d=String(now.getDate());if(m.length<2)m="0"+m;if(d.length<2)d="0"+d;date.min=now.getFullYear()+"-"+m+"-"+d;}
}

function formatDate(value){if(!value)return "Select date";var d=new Date(value+"T00:00:00");if(isNaN(d.getTime()))return value;return d.toLocaleDateString("en-GB",{day:"2-digit",month:"short",year:"numeric"});}

function submitBooking(){var v=currentVehicle(),date=el("bookingDate"),action=el("formAction"),vehicle=el("bookingVehicle"),service=el("bookingServiceHidden"),dateH=el("bookingDateHidden"),timeH=el("bookingTimeHidden");if(!v){showToast("No vehicle is available.");return false;}if(!date || !date.value){showToast("Select a service date.");return false;}if(vehicle)vehicle.value=v.sys_id;if(service)service.value=autoCareState.selectedService;if(dateH)dateH.value=date.value;if(timeH)timeH.value=autoCareState.selectedTime;if(action)action.value="book";return true;}

function approveRepair(sysId){if(!sysId){showToast("Repair plan is missing.");return false;}var action=el("formAction"),repair=el("repairSysid");if(action)action.value="approve_repair";if(repair)repair.value=sysId;var form=document.querySelector("form");if(form)form.submit();return false;}

function saveProfile(){var name=el("profileName"),email=el("profileEmail"),action=el("formAction"),nameH=el("profileNameHidden"),emailH=el("profileEmailHidden");if(!name||!email)return false;if(!name.value.replace(/^\s+|\s+$/g,"")){showToast("Display name is required.");return false;}if(nameH)nameH.value=name.value;if(emailH)emailH.value=email.value;if(action)action.value="save_profile";return true;}

function showToast(message){var toast=el("toast");if(!toast)return;toast.textContent=message;toast.style.display="block";window.clearTimeout(window.autoCareToastTimer);window.autoCareToastTimer=window.setTimeout(function(){toast.style.display="none";},3000);}

function initChat(){var open=el("chatOpen"),chat=el("chatbot"),close=el("closeChat");if(open)open.addEventListener("click",function(){chat.style.display="flex";open.style.display="none";});if(close)close.addEventListener("click",function(){chat.style.display="none";open.style.display="flex";});var qs=document.querySelectorAll(".quick-option");for(var i=0;i<qs.length;i++){qs[i].addEventListener("click",function(){var option=this.getAttribute("data-option");addUserMessage(option);if(option.indexOf("Health")>=0)go("healthPassport");else if(option.indexOf("Recommendation")>=0)go("recommendations");else if(option.indexOf("Appointment")>=0)go("appointments");else if(option.indexOf("Inspection")>=0)go("inspection");else if(option.indexOf("Repair")>=0)go("repair");else if(option.indexOf("Invoice")>=0)go("invoices");setTimeout(function(){addBotMessage(getChatResponse(option));}.bind(this),180);});}}
function addUserMessage(m){var b=el("chatBody");if(!b)return;var d=document.createElement("div");d.className="message user-message";d.textContent=m;b.appendChild(d);b.scrollTop=b.scrollHeight;}
function addBotMessage(m){var b=el("chatBody");if(!b)return;var d=document.createElement("div");d.className="message bot-message";d.textContent=m;b.appendChild(d);b.scrollTop=b.scrollHeight;}
function sendMessage(){var input=el("chatInput");if(!input)return;var m=input.value.replace(/^\s+|\s+$/g,"");if(!m)return;addUserMessage(m);input.value="";setTimeout(function(){addBotMessage(getChatResponse(m));},200);}
function getChatResponse(message){var t=String(message||"").toLowerCase(),v=currentVehicle(),r=recordsForVehicle(autoCareState.data.recommendations,v),i=recordsForVehicle(autoCareState.data.inspections,v);if(t.indexOf("health")>=0)return "Your Vehicle Health Passport currently shows a calculated health score of "+calculateHealth(v).score+" based on stored inspection and recommendation signals.";if(t.indexOf("recommend")>=0||t.indexOf("maintenance")>=0)return r.length?"There are "+r.length+" recommendation records. The latest action is: "+(r[0].action||"not recorded")+".":"No recommendation records are available.";if(t.indexOf("appointment")>=0||t.indexOf("book")>=0)return "Open Appointments, select a service, date and time, then confirm. The record is inserted into the Appointment table.";if(t.indexOf("inspection")>=0)return i.length?"There are "+i.length+" inspection records. The latest finding is: "+(i[0].finding||i[0].technician_notes||"not recorded")+".":"No inspection records are available.";if(t.indexOf("repair")>=0)return "Repair Plan displays backend repair plans and provides an Approve action for pending owner approval.";if(t.indexOf("invoice")>=0)return "Invoices displays live invoice, amount, payment and document status records.";return "I can help with vehicle health, recommendations, appointments, inspections, repair plans, service history and invoices.";}

function renderBackendStatus(){var b=autoCareState.data.backend||{},t=b.tables||{},keys=["vehicles","appointments","inspections","recommendations","repairs","outcomes","history","invoices"],valid=0;for(var i=0;i<keys.length;i++){if(t[keys[i]]&&t[keys[i]].valid&&t[keys[i]].readable)valid++;}var connected=valid===keys.length;var dot=el("backendDot"),status=el("backendStatus"),details=el("backendDetails");if(dot)dot.className="status-dot "+(connected?"connected":"error");if(status)status.textContent=connected?"Connected to AutoCare AI backend":"Backend table access needs attention";if(details){var d="Vehicles: "+(autoCareState.data.vehicles||[]).length+" | Appointments: "+(autoCareState.data.appointments||[]).length+" | Inspections: "+(autoCareState.data.inspections||[]).length+" | Recommendations: "+(autoCareState.data.recommendations||[]).length+" | Repair Plans: "+(autoCareState.data.repairs||[]).length+" | Outcomes: "+(autoCareState.data.outcomes||[]).length+" | History: "+(autoCareState.data.history||[]).length+" | Invoices: "+(autoCareState.data.invoices||[]).length;if(b.error)d+=" | Error: "+b.error;details.textContent=d;}}

function renderAll(){renderHome();renderPassport();renderRecommendations();renderAppointments();renderInspection();renderRepair();renderOutcomes();renderHistory();renderInvoices();renderProfile();}


function loadAutoCareData(callback) {
    var loading = el("dataLoading");
    if (loading) loading.style.display = "block";
    var ga = new GlideAjax("AutoCareUIDataAjax");
    ga.addParam("sysparm_name", "getData");
    ga.getXMLAnswer(function(answer) {
        var data = null;
        try { data = JSON.parse(answer || "{}"); } catch (e) { data = null; }
        if (!data || !data.backend) {
            autoCareState.data = {user:{},vehicles:[],appointments:[],inspections:[],recommendations:[],repairs:[],outcomes:[],history:[],invoices:[],backend:{error:"The backend response could not be parsed."}};
        } else {
            autoCareState.data = data;
        }
        autoCareState.currentVehicleId = autoCareState.data.vehicles && autoCareState.data.vehicles.length ? autoCareState.data.vehicles[0].sys_id : "";
        if (loading) loading.style.display = "none";
        if (callback) callback();
    });
}

function autoCareInit(){
    initNavigation();
    initVehicleSelector();
    initTabs();
    initBooking();
    initChat();
    loadAutoCareData(function(){
        renderAll();
        renderBackendStatus();
        go("home");
    });
}

if(document.readyState==="loading") document.addEventListener("DOMContentLoaded",autoCareInit); else autoCareInit();

sys_ui_page.processing_script:
if (action == "approve_repair") {
    var repairId = (repair_sysid || "").toString();
    if (!repairId) {
        gs.addErrorMessage("Repair plan record is required.");
    } else {
        var repair = new GlideRecordSecure("x_1947064_autoca_0_repair_plan");
        if (!repair.get(repairId)) {
            gs.addErrorMessage("Repair plan could not be found.");
        } else {
            if (repair.isValidField("owner_approval")) repair.setValue("owner_approval", "approved");
            if (repair.isValidField("approval_date")) repair.setValue("approval_date", gs.nowDateTime());
            if (repair.isValidField("status")) repair.setValue("status", "approved");
            var updated = repair.update();
            if (updated) gs.addInfoMessage("Repair plan approved successfully.");
            else gs.addErrorMessage("Repair plan approval failed.");
        }
    }
} else if (action == "book") {
    var vehicleId = (booking_vehicle || "").toString();
    var serviceType = (booking_service || "").toString();
    var appointmentDate = (booking_date || "").toString();
    var preferredTime = (booking_time || "").toString();
    if (!vehicleId || !appointmentDate || !serviceType) {
        gs.addErrorMessage("Vehicle, service and date are required.");
    } else {
        var vehicle = new GlideRecordSecure("x_1947064_autoca_0_vehicle");
        if (!vehicle.get(vehicleId)) {
            gs.addErrorMessage("The selected vehicle could not be found.");
        } else {
            var appt = new GlideRecordSecure("x_1947064_autoca_0_appointment");
            appt.initialize();
            if (appt.isValidField("appointment_number")) appt.setValue("appointment_number", "APT-" + new GlideDateTime().getNumericValue());
            if (appt.isValidField("vehicle")) appt.setValue("vehicle", vehicle.getUniqueValue());
            if (appt.isValidField("owner")) appt.setValue("owner", vehicle.getValue("owner"));
            if (appt.isValidField("appointment_date")) appt.setValue("appointment_date", appointmentDate);
            if (appt.isValidField("preferred_date")) appt.setValue("preferred_date", appointmentDate);
            if (appt.isValidField("preferred_time")) appt.setValue("preferred_time", preferredTime);
            if (appt.isValidField("service_type")) appt.setValue("service_type", serviceType);
            if (appt.isValidField("status")) appt.setValue("status", "pending");
            if (appt.isValidField("customer_contact")) appt.setValue("customer_contact", gs.getUser().getEmail());
            if (appt.isValidField("notes")) appt.setValue("notes", "Created from AutoCare AI Vehicle Health Passport UI.");
            var newId = appt.insert();
            if (newId) gs.addInfoMessage("Appointment created successfully.");
            else gs.addErrorMessage("Appointment could not be created.");
        }
    }
} else if (action == "save_profile") {
    var profileNameValue = (profile_name || "").toString();
    var profileEmailValue = (profile_email || "").toString();
    var user = new GlideRecordSecure("sys_user");
    if (!user.get(gs.getUserID())) {
        gs.addErrorMessage("Your ServiceNow user record could not be found.");
    } else {
        if (profileNameValue && user.isValidField("name")) user.setValue("name", profileNameValue);
        if (user.isValidField("email")) user.setValue("email", profileEmailValue);
        var saved = user.update();
        if (saved) gs.addInfoMessage("Profile updated successfully.");
        else gs.addErrorMessage("Profile update could not be completed.");
    }
}
